// === Variables ===
// Base
var plans_selectedProduct = "127c5796-4f77-5797-bce0-cc16597310f9";

// Derived
var $state_el_017S = undefined;
var $selectedIndex_plans = undefined;

// === Derived ===
const _derived = {
  $state_el_017S: [
    () => {
      let s = "";
      if (_.isSelected("el_017S")) s = "selected";
      return s;
    },
    ["plans_selectedProduct"]
  ],
  $selectedIndex_plans: [() => _.selectedIndex("plans"), ["plans_selectedProduct"]]
};

// === Recompute ===
const _recompute = (name) => {
  for (const key in _derived) {
    const entry = _derived[key]
    if (entry[1].indexOf(name) === -1) continue
    _.setVar(key, entry[0]())
  }
}

const _recomputeAll = () => {
  for (const key in _derived) {
    _.setVar(key, _derived[key][0]())
  }
}

// === Metadata ===
const _meta = {
  screens: [
    { id: "scr_paywall", progress: { enabled: false } }
  ],
  elements: {
    "el_017S": { screenId: "scr_paywall", selectableData: { groupId: "plans", groupType: "product", flowProductId: "127c5796-4f77-5797-bce0-cc16597310f9" } }
  }
};

// === Nav State ===
const _nav = { stack: []}

// === Internals ===
const _ = {
  getVar: (name) => (globalThis)[name],

  setVar: (name, value) => {
    const g = globalThis
    if (g[name] === value) return
    g[name] = value
    _recompute(name)
  },

  isSelected: (elementId) => {
    const entry = _meta.elements[elementId]
    const sel = entry && entry.selectableData
    if (!sel) return false
    switch (sel.groupType) {
      case 'single_choice':
        return _.getVar(sel.groupId + '_selectedOptionId') === sel.optionId
      case 'multi_choice':
        return (
          (_.getVar(sel.groupId + '_selectedOptionIds')).indexOf(
            sel.optionId,
          ) !== -1
        )
      case 'toggle':
        return Boolean(_.getVar(sel.groupId + '_isActive'))
      case 'product':
        return _.getVar(sel.groupId + '_selectedProduct') === sel.flowProductId
      default:
        return false
    }
  },

  selectedIndex: (groupId) => {
    const screen = _nav.stack[_nav.stack.length - 1]
    let i = 0
    for (const id in _meta.elements) {
      const e = _meta.elements[id]
      if (e.screenId !== screen) continue
      const sel = e.selectableData
      if (!sel || sel.groupId !== groupId) continue
      if (_.isSelected(id)) return i
      i += 1
    }
    return -1
  },

  selectProduct: (elementId) => {
    const entry = _meta.elements[elementId]
    const sel = entry && entry.selectableData
    if (!sel) return
    const groupId = sel.groupId
    _.setVar(groupId + '_selectedProduct', sel.flowProductId)
    SDK.onSelectProduct({ productId: sel.flowProductId})
  },

  purchase: (payload) => {
    if (payload.type === 'web') {
      SDK.webPurchaseProduct({
        productId: payload.product,
        openIn: payload.external ? 'browser_out_app': 'browser_in_app',
      })
    } else {
      SDK.purchaseProduct({ productId: payload.product})
    }
  },

  nav: (screenId) => {
    _nav.stack.push(screenId)
    _recomputeAll()
    SDK.openScreen({ type: screenId, instanceId: screenId, transitionId: 'forward'})
  }
};

// === Handlers ===
function on_el_017S_tap() {
  _.selectProduct("el_017S");
}

function on_el_025S_tap() {
  _.purchase({ type: "native", product: plans_selectedProduct, webPaywallURL: "", external: false });
}

function on_el_027S_tap() {
  SDK.openUrl({ url: "https://go.blokada.org/terms_family", openIn: "browser_in_app" });
}

function on_el_029S_tap() {
  SDK.openUrl({ url: "https://go.blokada.org/privacy_family", openIn: "browser_in_app" });
}

function on_el_031S_tap() {
  SDK.restorePurchases();
}

function on_el_035S_tap() {
  SDK.closeAll();
}

function on_scr_paywall_appear() {
  SDK.sendAnalyticsEvent({
    name: "flow_screen_showed",
    instanceId: "scr_paywall",
    screen_order: 1,
    is_last_screen: true,
    isBackendEvent: true,
    isCustomerEvent: true,
  });
}

// === Init ===
for (const key in _derived) {
  _.setVar(key, _derived[key][0]())
}
_.nav(_meta.screens[0].id)
